function sanitizeName(name) {
  if (name == null) return "";
  return name.replace(/[^a-zA-Z0-9]/g, " ");
}

function extractMiddleName(fullName) {
  if (!fullName) return '';
  const nameParts = fullName.trim().split(' ');
  if (nameParts.length > 2) {
    return nameParts[1].charAt(0).toUpperCase();
  }
  return '';
}

const personal = payload.personalInformation;

if (!personal) {
  return { exit: true };
}

const firstName = personal.firstName;
const lastName = personal.lastName;
const middleName = extractMiddleName(firstName);

return {
  firstName: sanitizeName(firstName),
  lastName: sanitizeName(lastName),
  middleName: middleName
};

const constants = steps.constants.output;
const personal = payload.personalInformation;
const state = personal.state;
const validState = constants.states.includes(state);

const firstName = steps.parsed_name.output.firstName;
const lastName = steps.parsed_name.output.lastName;
const validName = firstName?.trim().length > 0 && lastName?.trim().length > 0;

const primaryPhone = personal.primaryPhone;
const validPhone = primaryPhone?.trim().length > 0;

const loanAmount = payload.loanInformation.loanAmount;
const annualIncome = payload.financialInformation.annualIncome;
const purpose = payload.loanInformation.purpose;
const employmentStatus = payload.financialInformation.employmentStatus;
const qualifiedLead =
  loanAmount >= constants.minimumLoanAmount &&
  annualIncome >= constants.minimumAnnualIncome &&
  constants.allowedPurposes.includes(purpose) &&
  constants.allowedEmploymentStatuses.includes(employmentStatus);

const biddingActive = steps.custom_request.output.body.IsActive === true;

if (biddingActive && validState && validName && validPhone && qualifiedLead) {
  return { valid: true };
}

const headers = { "Content-Type": "application/json" };

if (!biddingActive) {
  console.log("Rejected: bidding not active");
  return { response: { status: 200, headers, body: { lead_id: payload.leadId1, status: "rejected", reason: "bidding not active" } } };
}
if (!validState) {
  console.log(`Rejected due to invalid_state: ${state}`);
  return { response: { status: 200, headers, body: { lead_id: payload.leadId1, status: "rejected", reason: "ineligible state" } } };
}
if (!validName) {
  console.log(`Rejected due to invalid name: firstName="${firstName}", lastName="${lastName}"`);
  return { response: { status: 200, headers, body: { lead_id: payload.leadId1, status: "rejected", reason: "invalid name" } } };
}
if (!validPhone) {
  console.log(`Rejected due to missing phone: primaryPhone="${primaryPhone}"`);
  return { response: { status: 200, headers, body: { lead_id: payload.leadId1, status: "rejected", reason: "missing phone" } } };
}
if (!qualifiedLead) {
  console.log(`Rejected due to unqualified lead: loanAmount=${loanAmount}, annualIncome=${annualIncome}, purpose="${purpose}"`);
  return { response: { status: 200, headers, body: { lead_id: payload.leadId1, status: "rejected", reason: "unqualified_lead", requestId: execution.trace_id } } };
}

function transformToSalesforceFormat(inputData, parsedName) {
  const personal = inputData.personalInformation || {};
  const loan = inputData.loanInformation || {};
  const mortgage = inputData.mortgageInformation || {};
  const credit = inputData.creditInformation || {};
  const financial = inputData.financialInformation || {};
  const education = inputData.educationInformation || {};
  const legal = inputData.legalInformation || {};

  const mapEmploymentStatus = (status) => {
    if (!status) return 'Other';
    const statusMap = {
      'employed': 'Employed', 'employed_full_time': 'employed_full_time',
      'employed_part_time': 'employed_part_time', 'military': 'Military',
      'not_employed': 'not_employed', 'self_employed': 'self_employed',
      'retired': 'Retired', 'other': 'Other'
    };
    return statusMap[status.toLowerCase()] || 'Other';
  };

  const mapEducationLevel = (level) => {
    if (!level) return 'Other';
    const levelMap = {
      'high_school': 'high_school', 'associate': 'Associate', 'bachelors': 'Bachelors',
      'masters': 'Masters', 'doctorate': 'Doctorate', 'other_grad_degree': 'other_grad_degree',
      'certificate': 'Certificate', 'did_not_graduate': 'did_not_graduate',
      'still_enrolled': 'still_enrolled', 'other': 'Other'
    };
    return levelMap[level.toLowerCase()] || 'Other';
  };

  const mapLoanPurpose = (purpose) => {
    if (!purpose) return 'Other';
    const purposeMap = {
      'auto': 'Auto', 'auto_purchase': 'auto_purchase', 'auto_refinance': 'auto_refinance',
      'baby': 'Baby', 'boat': 'Boat', 'business': 'Business', 'car_repair': 'car_repair',
      'cosmetic': 'Cosmetic', 'credit_card_refi': 'credit_card_refi',
      'debt_consolidation': 'debt_consolidation', 'emergency': 'Emergency',
      'engagement': 'Engagement', 'green': 'Green', 'home_improvement': 'home_improvement',
      'home_purchase': 'home_purchase', 'home_refi': 'home_refi',
      'household_expenses': 'household_expenses', 'large_purchases': 'large_purchases',
      'life_event': 'life_event', 'medical_dental': 'medical_dental', 'motorcycle': 'Motorcycle',
      'moving_relocation': 'moving_relocation', 'other': 'Other', 'rv': 'Rv',
      'special_occasion': 'special_occasion', 'student_loan': 'student_loan',
      'student_loan_refi': 'student_loan_refi', 'taxes': 'Taxes', 'unknown': 'Unknown',
      'vacation': 'Vacation', 'wedding': 'Wedding'
    };
    return purposeMap[purpose.toLowerCase()] || 'Other';
  };

  const mapPaymentFrequency = (frequency) => {
    if (!frequency) return 'Monthly';
    const frequencyMap = { 'weekly': 'Weekly', 'biweekly': 'biweekly', 'twice_monthly': 'twice_monthly', 'monthly': 'Monthly' };
    return frequencyMap[frequency.toLowerCase()] || 'Monthly';
  };

  const mapCreditRating = (rating) => {
    if (!rating) return 'Poor (<600)';
    const ratingMap = {
      'excellent': 'Excellent (720+)', 'good': 'Good (660-719)', 'fair': 'Fair (620-659)',
      'poor': 'Poor (<600)', 'limited': 'Poor (<600)', 'unknown': 'Poor (<600)'
    };
    return ratingMap[rating.toLowerCase()] || 'Poor (<600)';
  };

  const mapPropertyStatus = (status) => {
    if (!status) return 'Rent';
    const statusMap = { 'own_outright': 'Own Outright', 'own_with_mortgage': 'Own with Mortgage', 'rent': 'Rent' };
    return statusMap[status.toLowerCase()] || 'Rent';
  };

  const formatPhoneNumber = (phone) => {
    if (!phone) return '';
    const digits = phone.replace(/\D/g, '');
    if (digits.length === 10) {
      return `(${digits.slice(0, 3)}) ${digits.slice(3, 6)}-${digits.slice(6)}`;
    }
    return phone;
  };

  const formatSSN = (ssn) => {
    if (!ssn) return '';
    return ssn.replace(/\D/g, '');
  };

  return {
    "Last_Name__c": parsedName.lastName || '',
    "Middle_Name__c": parsedName.middleName || '',
    "First_Name__c": parsedName.firstName || '',
    "State__c": personal.state || '',
    "City__c": personal.city || '',
    "Zip__c": personal.zipcode || '',
    "Email__c": personal.email || '',
    "Phone__c": formatPhoneNumber(personal.primaryPhone),
    "BirthDate__c": personal.dateOfBirth || '',
    "Street__c": personal.address1 || '',
    "AptSuite__c": personal.address2 || '',
    "LoanAmount__c": loan.loanAmount || 0,
    "LoanPurpose__c": mapLoanPurpose(loan.loanPurpose),
    "IncomePmtFrequency__c": mapPaymentFrequency(financial.payFrequency),
    "AnnualIncomeBeforeTaxes__c": financial.annualIncome || 0,
    "EmploymentStatus__c": mapEmploymentStatus(financial.employmentStatus),
    "EducationLevel__c": mapEducationLevel(education.educationLevel),
    "SocialSecurityNumber__c": formatSSN(personal.ssn),
    "RentOrOwn__c": mapPropertyStatus(mortgage.propertyStatus),
    "ApproximateCreditRating__c": mapCreditRating(credit.creditScore),
    "Lead_Economy_Lead_UUID__c": inputData.leadId1,
    "Source__c": "Lead Economy",
    "TCPAConsentFlag__c": legal.consentsToTcpa,
    "FCRAConsentFlag__c": legal.consentsToFcra,
    "Lead_ID_TI__c": inputData.leadId1,
    "Publisher_ID_TI__c": inputData.leadId2,
    "Campaign_ID_TI__c": inputData.leadId3,
    "Custom_ID_TI__c": inputData.leadId4
  };
}

try {
  return transformToSalesforceFormat(payload, steps.parsed_name.output);
} catch (error) {
  console.error('Error transforming data:', error);
  return { response: { status: 500, body: { lead_id: payload.leadId1, status: "error", reason: "internal server error" } } };
}

async function getEquifaxToken(username, password) {
  const params = 'grant_type=client_credentials&scope=https://api.equifax.com/business/oneview/consumer-credit/v1';
  const res = await fetch('https://api.equifax.com/v2/oauth/token', {
    method: 'POST',
    headers: {
      'Content-Type': 'application/x-www-form-urlencoded',
      'Authorization': 'Basic ' + btoa(`${username}:${password}`),
      'User-Agent': 'axios/1.7.0',
      'Accept': 'application/json, text/plain, */*',
    },
    body: params,
  });
  if (!res.ok) {
    const text = await res.text();
    throw new Error(`Equifax Token Error: ${res.status} - ${text}`);
  }
  const data = await res.json();
  if (!data.access_token) throw new Error('Access token not found in response');
  return data.access_token;
}

function formatRequestBody(body, firstName, lastName) {
  if (!body.ssn) throw new Error('personalInformation.ssn missing from payload');
  if (!body.dateOfBirth) throw new Error('personalInformation.dateOfBirth missing from payload');

  const formattedSSN = String(body.ssn).replace(/[^0-9]/g, '').slice(0, 9);
  if (formattedSSN.length !== 9) {
    throw new Error(`SSN must contain 9 digits after stripping non-numerics; got ${formattedSSN.length} from "${body.ssn}"`);
  }

  const [year, month, day] = body.dateOfBirth.split('-');
  const formattedDOB = `${month}${day}${year}`;

  return {
    consumers: {
      name: [{
        identifier: 'current',
        firstName,
        lastName,
        middleName: '',
        suffix: '',
      }],
      socialNum: [{
        identifier: 'current',
        number: formattedSSN,
      }],
      dateOfBirth: formattedDOB,
      addresses: [{
        identifier: 'current',
        streetName: `${body.address1 ?? ''} ${body.address2 ?? ''}`.trim(),
        city: body.city,
        state: body.state,
        zip: body.zipcode,
      }],
    },
    customerReferenceIdentifier: 'Pennie Management',
    customerConfiguration: {
      equifaxUSConsumerCreditReport: {
        memberNumber: '402FZ14896',
        securityCode: 'N2N',
        pdfComboIndicator: 'N',
        customerCode: 'ISTS',
        multipleReportIndicator: '1',
        ECOAInquiryType: 'Individual',
        models: [{ identifier: '05402' }],
        endUserInformation: {
          endUsersName: '',
          permissiblePurposeCode: 'Null',
        },
      },
    },
  };
}

async function makeEquifaxRequest(token, body) {
  const res = await fetch(
    'https://api.equifax.com/business/oneview/consumer-credit/v1/reports/credit-report',
    {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Authorization': `Bearer ${token}`,
        'User-Agent': 'axios/1.7.0',
        'Accept': 'application/json, text/plain, */*',
      },
      body: JSON.stringify(body),
    }
  );
  if (!res.ok) {
    const text = await res.text();
    return { error: true, statusCode: res.status, message: text };
  }
  const data = await res.json();
  return { error: false, statusCode: 200, data };
}

async function makeEquifaxRequestWithRetry(token, body) {
  let result = await makeEquifaxRequest(token, body);
  if (result.error && result.statusCode >= 500 && result.statusCode < 600) {
    console.log(`Equifax first attempt failed ${result.statusCode}, retrying after 250ms...`);
    await new Promise(r => setTimeout(r, 250));
    result = await makeEquifaxRequest(token, body);
  }
  return result;
}

const personal = payload.personalInformation ?? {};
const body = { ...personal, leadUuid: payload.leadId1 };
const firstName = steps.parsed_name.output.firstName;
const lastName = steps.parsed_name.output.lastName;

try {
  const accessToken = await getEquifaxToken(
    env.EQUIFAX_USERNAME,
    env.EQUIFAX_PASSWORD
  );

  const formattedBody = formatRequestBody(body, firstName, lastName);
  const result = await makeEquifaxRequestWithRetry(accessToken, formattedBody);

  if (result.error) {
    console.error(`Equifax credit report error [${execution.trace_id}]: ${result.statusCode} - ${result.message}`);
    return {
      response: {
        status: result.statusCode ?? 500,
        body: {
          lead_id: body.leadUuid,
          status: 'error',
          reason: 'equifax_api_error',
          upstream_status: result.statusCode,
          upstream_body: (() => { try { return JSON.parse(result.message); } catch { return result.message; } })(),
        },
      },
    };
  }

  return result.data;
} catch (error) {
  console.error(`Error in equifax_credit_report [${execution.trace_id}]:`, error.message, error.stack);
  return {
    response: {
      status: 500,
      body: {
        lead_id: body.leadUuid,
        status: 'error',
        reason: 'equifax_script_error',
        error_message: error?.message ?? String(error),
      },
    },
  };
}

const eqxCreditReport = steps.equifax_credit_report.output;
const {
  consumers: {
    equifaxUSConsumerCreditReport: [creditReport = {}] = []
  } = {}
} = eqxCreditReport;
const trades = creditReport.trades || [];

console.log(`Credit Report: ${eqxCreditReport.status}, with ${trades.length} trades.`);

const prospectId = steps.create_prospect.output.body.id;

if (eqxCreditReport.status !== 'completed' || trades.length === 0) {
  return {
    response: {
      status: 200,
      body: { lead_id: payload.leadId1, requestId: execution.trace_id, status: "rejected", reason: "missing_credit_check" },
    },
    continueExecution: true,
    hasCreditMatch: false,
    prospectId: prospectId,
  };
}

const score = creditReport.models?.find(model => model.modelNumber === "05402")?.score;
const removeNullValues = (obj) => Object.fromEntries(
  Object.entries(obj).filter(([_, value]) => value !== null)
);
const parsedTrades = trades.map(removeNullValues);

return {
  hasCreditMatch: true,
  prospectId: prospectId,
  tradesJson: JSON.stringify({ trades: parsedTrades }),
  vantageScore: score,
};

const pt = steps.prospect_trades.output.body;
const engineBid = pt.engineBid;

const rejectBody = {
  lead_id: payload.leadId1,
  status: "rejected",
  reason: "unqualified_lead",
};

if (engineBid === 0) {
  return { response: { status: 200, body: rejectBody }, continueExecution: true, isRejected: true };
}

let tripointResult = null;
if (pt.sellOff) {
  const proxyPayload = {
    ...payload,
    unsecuredDebt: pt.tradeCalculations.engineDebt,
    maxUnsecuredDebt: pt.tradeCalculations.enrollableDebt,
    workflowId: 'am-one-bidding',
    pennieLeadId: steps.create_prospect.output.body.id,
    executionId: execution.trace_id,
    leadType: 'prospect',
  };

  const res = await fetch('https://tripoint-proxy.trypennie.dev/leads/create', {
    method: 'POST',
    headers: {
      authorization: `Bearer ${env.TRIPOINT_PROXY_SECRET}`,
      'content-type': 'application/json',
    },
    body: JSON.stringify(proxyPayload),
  });
  const rawText = await res.text();
  let body = {};
  try { body = rawText ? JSON.parse(rawText) : {}; } catch {}
  const createLead = body?.data?.createLead ?? null;
  const resultCode = Number(createLead?.resultCode);
  const qualified =
    body.ok === true &&
    (resultCode === 1000 || resultCode === 1001 || (resultCode >= 1013 && resultCode <= 1017));

  console.log(`createLead resultCode=${resultCode} qualified=${qualified}`);
  tripointResult = { qualified, createLead, resultCode };

  if (!tripointResult.qualified) {
    return { response: { status: 200, body: rejectBody }, continueExecution: true, isRejected: true, tripointResult };
  }
}

const constants = steps.constants.output;

let redirectUrl;
if (pt.sellOff)              redirectUrl = constants.tripointClickUrl;
else if (pt.expLandingPage)  redirectUrl = constants.pennieExpLandingPage;
else if (pt.altLandingPage)  redirectUrl = constants.pennieAlternateClickUrl;
else                         redirectUrl = constants.pennieClickUrl;

const fmt = new Intl.NumberFormat('en-US');
const firstName = payload.personalInformation.firstName;
const formattedName = firstName.charAt(0).toUpperCase() + firstName.slice(1).toLowerCase();
const annualIncome = fmt.format(payload.financialInformation.annualIncome);
const maxLoanPmt = fmt.format(pt.maxLoanPmt);
const maxLoanAmt = fmt.format(pt.maxLoanAmt);

const dynamicOfferContent = {
  offer_title: `${formattedName}, you may qualify for up to $${maxLoanAmt} starting at $${maxLoanPmt}/mo.`,
  offer_details: "<ul><li>Terms and rates based on your income</li><li>Approval in minutes, not weeks</li><li>Funding as soon as the next business day</li></ul>",
};

let offer;
if (pt.sellOff) {
  offer = { offer_title: constants.sellOffOfferTitle, offer_details: constants.sellOffOfferDetails };
} else if (pt.testOfferLanguage) {
  offer = dynamicOfferContent;
} else {
  offer = { offer_title: constants.mainOfferTitle, offer_details: constants.mainOfferDetails };
}

// The hosts that get the link token (#2092): the block below signs a link to these only.
const LINK_TOKEN_HOSTS = ['trypennie.com', 'www.trypennie.com'];
// BEGIN link token (#2089)
// trypennie.com refuses a link to a Salesforce record created after its cutoff unless the
// link carries ?t=<token>: HMAC-SHA256 of the first 15 characters of the record id, keyed
// with LINK_TOKEN_SECRET, base64url with no padding, and reservemyloan.com is to check the
// same token. Salesforce's LinkToken class and the Pipedream helpers sign exactly the same
// way. Only a host in LINK_TOKEN_HOSTS, which each script sets just above this block, gets
// the token, never a partner's domain. With no secret the link goes out unsigned, an error
// is logged and `link_token` on this step's output says why; the run is never failed for
// it. This block is identical in every script that signs a link, and link-token.test.ts
// holds them all to one text (#2092).
const SALESFORCE_ID = /^[a-zA-Z0-9]{15}(?:[a-zA-Z0-9]{3})?$/;
const withLinkToken = async (url, recordId) => {
  let host = null;
  try { host = new URL(url).hostname; } catch {}
  if (!LINK_TOKEN_HOSTS.includes(host)) return { url, link_token: 'not_our_host' };
  if (typeof recordId !== 'string' || !SALESFORCE_ID.test(recordId)) return { url, link_token: 'no_record_id' };
  const secret = env.LINK_TOKEN_SECRET;
  if (typeof secret !== 'string' || !secret) {
    console.error('LINK_TOKEN_SECRET is not set, so the link went out without its token (#2089)');
    return { url, link_token: 'missing_secret' };
  }
  try {
    const enc = new TextEncoder();
    const key = await crypto.subtle.importKey('raw', enc.encode(secret), { name: 'HMAC', hash: 'SHA-256' }, false, ['sign']);
    const signature = new Uint8Array(await crypto.subtle.sign('HMAC', key, enc.encode(recordId.slice(0, 15))));
    let binary = '';
    for (const byte of signature) binary += String.fromCharCode(byte);
    const token = btoa(binary).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
    return { url: `${url}${url.includes('?') ? '&' : '?'}t=${token}`, link_token: 'signed' };
  } catch (err) {
    console.error(`signing the link failed, so it went out without its token (#2089): ${err && err.message}`);
    return { url, link_token: 'sign_failed' };
  }
};
// END link token (#2089)

const prospectId = steps.create_prospect.output.body.id;
const offerLink = await withLinkToken(`${redirectUrl}/${prospectId}`, prospectId);

const responseBody = {
  requestId: execution.trace_id,
  offers: [{
    name: constants.offerName,
    display_name: constants.offerName,
    rate: engineBid,
    click_url: offerLink.url,
    product_type: constants.productType,
    logo_src: constants.logoSrc,
    ...offer,
  }],
};

const respondedAt = new Date().toISOString();
return { response: { status: 200, body: responseBody }, continueExecution: true, isRejected: false, tripointResult, respondedAt, link_token: offerLink.link_token };

const constants = steps.constants.output;
const sellOff = steps.prospect_trades.output.body.sellOff;
const response = steps.return_response.output.response.body;
const respondedAt = steps.return_response.output.respondedAt;

let requestBody = {};

if (response.offers?.[0]?.rate) {
  requestBody = {
    BidAmount__c: response.offers[0].rate,
    BidStatus__c: "Bid",
    OfferLandingPage__c: response.offers[0].click_url,
    Bid_Response_Timestamp__c: respondedAt,
    Base_Bid__c: steps.prospect_trades.output.body?.baseBid,
    Collections_Bid_Discount__c: steps.prospect_trades.output.body?.discountApplied,
  };
  if (sellOff) {
    requestBody.ExternalPartnerName__c = "Tripoint";
    requestBody.ExternalDebtAmount__c = steps.prospect_trades.output.body?.tradeCalculations?.enrollableDebt;
    requestBody.ExternalRoutingCode__c = 2;
    requestBody.ExternalExchangeStatus__c = "Bid";
    requestBody.OfferLandingPage__c = response.offers[0].click_url;
    requestBody.Bid_Response_Timestamp__c = respondedAt;
  }
} else {
  requestBody = {
    BidStatus__c: "Rejected",
    RejectionReason__c: response.reason,
  };
}

return requestBody;
